-- GameVault Supabase feature layer
create table if not exists public.gamevault_favorites(user_id uuid not null references auth.users(id) on delete cascade,game_id bigint not null,created_at timestamptz not null default now(),primary key(user_id,game_id));
alter table public.gamevault_favorites enable row level security;
drop policy if exists "favorites own rows" on public.gamevault_favorites;
create policy "favorites own rows" on public.gamevault_favorites for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
grant select,insert,delete on public.gamevault_favorites to authenticated;
create table if not exists public.gamevault_chat_messages(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,display_name text not null,content text not null check(char_length(content) between 1 and 500),created_at timestamptz not null default now());
alter table public.gamevault_chat_messages enable row level security;
drop policy if exists "chat read signed in" on public.gamevault_chat_messages;
drop policy if exists "chat send as self" on public.gamevault_chat_messages;
create policy "chat read signed in" on public.gamevault_chat_messages for select to authenticated using(true);
create policy "chat send as self" on public.gamevault_chat_messages for insert to authenticated with check(user_id=(select auth.uid()));
grant select,insert on public.gamevault_chat_messages to authenticated;
create table if not exists public.gamevault_tickets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,subject text not null,message text not null,status text not null default 'open' check(status in('open','answered','closed')),admin_reply text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.gamevault_tickets enable row level security;
drop policy if exists "ticket owner or admin read" on public.gamevault_tickets;
drop policy if exists "ticket owner create" on public.gamevault_tickets;
drop policy if exists "ticket admin update" on public.gamevault_tickets;
create policy "ticket owner or admin read" on public.gamevault_tickets for select to authenticated using(user_id=(select auth.uid()) or public.is_gamevault_admin());
create policy "ticket owner create" on public.gamevault_tickets for insert to authenticated with check(user_id=(select auth.uid()));
create policy "ticket admin update" on public.gamevault_tickets for update to authenticated using(public.is_gamevault_admin()) with check(public.is_gamevault_admin());
grant select,insert,update on public.gamevault_tickets to authenticated;
create table if not exists public.gamevault_reports(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,game_id bigint,reason text not null,details text,status text not null default 'open' check(status in('open','reviewing','resolved','dismissed')),created_at timestamptz not null default now());
alter table public.gamevault_reports enable row level security;
drop policy if exists "report owner or admin read" on public.gamevault_reports;
drop policy if exists "signed in report create" on public.gamevault_reports;
drop policy if exists "admin manage reports" on public.gamevault_reports;
create policy "report owner or admin read" on public.gamevault_reports for select to authenticated using(user_id=(select auth.uid()) or public.is_gamevault_admin());
create policy "signed in report create" on public.gamevault_reports for insert to authenticated with check(user_id=(select auth.uid()));
create policy "admin manage reports" on public.gamevault_reports for update to authenticated using(public.is_gamevault_admin()) with check(public.is_gamevault_admin());
grant select,insert,update on public.gamevault_reports to authenticated;
create index if not exists gamevault_chat_created_idx on public.gamevault_chat_messages(created_at desc);
create index if not exists gamevault_tickets_user_idx on public.gamevault_tickets(user_id,created_at desc);
create index if not exists gamevault_reports_created_idx on public.gamevault_reports(created_at desc);
do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='gamevault_chat_messages') then alter publication supabase_realtime add table public.gamevault_chat_messages; end if; exception when undefined_object then null; end $$;
create or replace function app_private.gamevault_handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.users(id,username,display_name,role) values(new.id,coalesce(nullif(split_part(new.email,'@',1),''),'player'),coalesce(nullif(new.raw_user_meta_data->>'display_name',''),nullif(split_part(new.email,'@',1),''),'Player'),'user') on conflict(id) do nothing; return new; end; $$;
revoke all on function app_private.gamevault_handle_new_user() from public,anon,authenticated;
drop trigger if exists gamevault_on_auth_user_created on auth.users;
create trigger gamevault_on_auth_user_created after insert on auth.users for each row execute function app_private.gamevault_handle_new_user();
